CREATE TABLE api_keys ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, scope VARCHAR(8) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, expires_at DATETIME, blocked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE auth_sessions ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, account_id INTEGER NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, ip VARCHAR(64) NOT NULL, user_agent VARCHAR(255) NOT NULL, uid VARCHAR(32) DEFAULT '' NOT NULL, remember BOOLEAN DEFAULT 1 NOT NULL, stage VARCHAR(8) DEFAULT 'full' NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, revoked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE email_confirmations ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, address VARCHAR(255) NOT NULL, token_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (account_id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE invites ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, email VARCHAR(255) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE passkeys ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, credential_id BLOB NOT NULL, public_key BLOB NOT NULL, sign_count INTEGER NOT NULL, name VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE password_resets ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE push_devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, endpoint_key VARCHAR(64) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), CONSTRAINT uq_push_devices_uid UNIQUE (uid), CONSTRAINT uq_push_devices_user_endpoint UNIQUE (user_id, endpoint_key), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE settings ( "key" VARCHAR(64) NOT NULL, value JSON, PRIMARY KEY ("key") );
CREATE TABLE users ( id INTEGER NOT NULL, name VARCHAR(64) NOT NULL, display_name VARCHAR(80) NOT NULL, whats_new_seen VARCHAR(32) NOT NULL, role VARCHAR(16) NOT NULL, sign_in VARCHAR(16) NOT NULL, password_hash VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, email_confirmed_at DATETIME, email_from_provider BOOLEAN DEFAULT 0 NOT NULL, oidc_subject VARCHAR(255) NOT NULL, language VARCHAR(16) NOT NULL, profile JSON, created_at DATETIME NOT NULL, last_seen_at DATETIME, failed_logins INTEGER NOT NULL, locked_until DATETIME, blocked_at DATETIME, totp_secret_enc TEXT NOT NULL, totp_recovery TEXT NOT NULL, totp_last_step INTEGER NOT NULL, avatar BLOB, avatar_at DATETIME, signed_in_before BOOLEAN DEFAULT 0 NOT NULL, passkey_handle VARCHAR(64) DEFAULT '' NOT NULL, ai_allowed BOOLEAN DEFAULT 1 NOT NULL, PRIMARY KEY (id), UNIQUE (name) );
CREATE INDEX ix_api_keys_account_id ON api_keys (account_id);
CREATE INDEX ix_auth_sessions_account_id ON auth_sessions (account_id);
CREATE INDEX ix_devices_account_id ON devices (account_id);
CREATE INDEX ix_passkeys_user_id ON passkeys (user_id);
CREATE INDEX ix_password_resets_account_id ON password_resets (account_id);
CREATE INDEX ix_push_devices_user_id ON push_devices (user_id);
CREATE UNIQUE INDEX uq_auth_sessions_uid ON auth_sessions (uid);
CREATE UNIQUE INDEX uq_devices_uid ON devices (uid);
CREATE UNIQUE INDEX uq_passkeys_credential ON passkeys (credential_id);
CREATE UNIQUE INDEX uq_passkeys_uid ON passkeys (uid);
